pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GDG {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x048FFa8aAE293470932388b615A90A8265bFB25F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = GDG(TARGET).owner();

        // Impersonate the owner and set maxTxAmount to 1
        vm.prank(owner);
        GDG(TARGET).setMaxTxAmount(1);

        // Verify the exploit worked
        uint256 newMaxTx = GDG(TARGET)._maxTxAmount();
        require(newMaxTx == 1, "Exploit failed: _maxTxAmount not set to 1");
        assertEq(newMaxTx, 1, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

